def transform(grid):
    """Compress each 3x3 cell: use its most frequent color, with 5 as background."""
    h, w = len(grid), len(grid[0])
    if h % 3 or w % 3:
        raise ValueError('grid dimensions must be multiples of 3')
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            counts = {}
            for y in range(r, r + 3):
                for x in range(c, c + 3):
                    v = grid[y][x]
                    if v != 5:
                        counts[v] = counts.get(v, 0) + 1
            row.append(max(counts, key=counts.get) if counts else 0)
        out.append(row)
    return out
